        if v > 0:
            return 1
        if v < 0:
            return -1
        return 0

    def as_pair(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return None

    def get_pos(obs):
        for key in ("agent_pos", "position", "pos", "self_pos", "my_pos", "loc", "location"):
            p = as_pair(obs.get(key))
            if p is not None:
