                pts.append((obj[0], obj[1]))
                return pts
            for v in obj:
                pts.extend(extract_points(v))
        return pts

    def nearest(src, points):
        if src is None or not points:
            return None
        sx, sy = src
        best = None
        best_d = None
        for px, py in points:
            d = abs(px - sx) + abs(py - sy)
            if best_d is None or d < best_d:
